import {answer} from './engine.js';
const $=id=>document.getElementById(id), key='giordani-financas-v1';
let chats=[], current=null, busy=false;
try { const saved=JSON.parse(localStorage.getItem(key)); if(Array.isArray(saved)) chats=saved.filter(c=>c&&typeof c.id==='string'&&Array.isArray(c.messages)).slice(0,20); } catch {}
function save(){try{localStorage.setItem(key,JSON.stringify(chats));}catch{}}
function element(tag,text,cls){const node=document.createElement(tag); if(text!=null)node.textContent=String(text);if(cls)node.className=cls;return node;}
function renderHistory(){ $('history').replaceChildren();for(const c of chats){const b=element('button',c.title,c.id===current?'active':'');b.onclick=()=>{if(!busy){current=c.id;render();}};$('history').append(b);} }
function renderMessage(m){const box=element('article',null,'message '+m.role);box.append(element('div',m.role==='user'?'V':'G','avatar'));const body=element('div',null,'bubble');body.append(element('div',m.role==='user'?'Você':'Assistente Giordani','role'),element('div',m.text,'body'));if(m.table){const wrap=element('div',null,'table-wrap'),table=element('table'),thead=element('thead'),tr=element('tr');for(const h of m.table.headers){const th=element('th',h);th.scope='col';tr.append(th);}thead.append(tr);table.append(thead);const tb=element('tbody');for(const row of m.table.rows){const r=element('tr');for(const value of row)r.append(element('td',value));tb.append(r);}table.append(tb);wrap.append(table);body.append(wrap);}if(m.source)body.append(element('div',m.source,'source'));box.append(body);$('messages').append(box);}
function render(){renderHistory();$('messages').replaceChildren();const chat=chats.find(c=>c.id===current);for(const m of chat?.messages||[])renderMessage(m);}
function newChat(){if(busy)return;const c={id:crypto.randomUUID(),title:'Nova conversa',messages:[{role:'assistant',text:'Olá! Sou o assistente Giordani. O que você quer entender sobre esta amostra financeira? Escolha uma sugestão ou escreva sua pergunta.'}]};chats.unshift(c);chats=chats.slice(0,20);current=c.id;save();render();}
async function send(question){if(busy||!question.trim())return;const text=question.trim().slice(0,500),filter={account:$('account').value,start:$('start').value,end:$('end').value};const chat=chats.find(c=>c.id===current);busy=true;$('send').disabled=true;$('question').value='';if(chat.messages.length===1)chat.title=text;chat.messages.push({role:'user',text});render();const waiting=element('div','Consultando a amostra…','source');$('messages').append(waiting);try{await new Promise(r=>setTimeout(r,220));const response=answer(text,filter);chat.messages.push({role:'assistant',...response});chat.messages=chat.messages.slice(-80);}catch{chat.messages.push({role:'assistant',text:'Não foi possível consultar a amostra. Tente novamente ou restaure os filtros.'});}finally{busy=false;$('send').disabled=false;save();render();$('question').focus();$('composer').scrollIntoView({block:'end'});}}
$('composer').onsubmit=e=>{e.preventDefault();send($('question').value);};$('question').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();send($('question').value);}};
for(const button of document.querySelectorAll('.suggestions button'))button.onclick=()=>send(button.textContent);
$('new').onclick=newChat;$('clear').onclick=()=>{if(!busy&&confirm('Excluir o histórico salvo neste navegador?')){chats=[];newChat();}};
$('reset').onclick=()=>{$('account').value='';$('start').value='2026-09-28';$('end').value='2026-10-16';};$('about').onclick=()=>$('info').showModal();$('close').onclick=()=>$('info').close();
if(chats.length){current=chats[0].id;render();}else newChat();
